<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php';
require_login();
$config=__DIR__.'/config/database.php';
if(!is_file($config)){http_response_code(503);exit('Database configuration is not ready.');}
require $config;
$bid=current_business_id();
$stmt=$pdo->prepare('SELECT business_name,address,phone,pan_vat FROM businesses WHERE id=? AND is_active=1');$stmt->execute([$bid]);$business=$stmt->fetch();if(!$business){logout_user();header('Location: login.php');exit;}
function one(PDO $pdo,string $sql,array $args):float{$s=$pdo->prepare($sql);$s->execute($args);return (float)$s->fetchColumn();}
$products=one($pdo,'SELECT COUNT(*) FROM products WHERE business_id=? AND is_active=1',[$bid]);
$suppliers=one($pdo,'SELECT COUNT(*) FROM suppliers WHERE business_id=? AND is_active=1',[$bid]);
$parties=one($pdo,'SELECT COUNT(*) FROM parties WHERE business_id=? AND is_active=1',[$bid]);
$todaySales=one($pdo,"SELECT COALESCE(SUM((SELECT COALESCE(SUM(si.qty*si.rate),0) FROM sale_items si WHERE si.sale_id=s.id)-s.discount+s.vat_amount),0) FROM sales s WHERE s.business_id=? AND s.sale_date=CURDATE() AND s.status='posted'",[$bid]);
$receivable=one($pdo,"SELECT COALESCE(SUM(due_amount),0) FROM sales WHERE business_id=? AND status='posted'",[$bid])-one($pdo,'SELECT COALESCE(SUM(amount),0) FROM payments WHERE business_id=?',[$bid]);
$receivable=max(0,$receivable);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MeroKhata Dashboard</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f6f9;color:#172033}.top{height:64px;background:#174f9b;color:white;display:flex;align-items:center;justify-content:space-between;padding:0 22px}.brand{font-size:24px;font-weight:800}.user{font-size:14px}.user a{color:white;margin-left:14px}.layout{display:grid;grid-template-columns:230px 1fr;min-height:calc(100vh - 64px)}aside{background:#fff;border-right:1px solid #e3e7ee;padding:18px 12px}aside a{display:block;text-decoration:none;color:#283447;padding:11px 13px;border-radius:8px;margin:3px 0}aside a.active,aside a:hover{background:#eaf2ff;color:#174f9b;font-weight:700}main{padding:25px}.sub{color:#667085;margin-top:-8px}.cards{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:15px;margin-top:22px}.card{background:white;padding:18px;border-radius:13px;box-shadow:0 2px 10px #1720330d}.card small{color:#667085}.num{font-size:25px;font-weight:800;margin-top:8px}.welcome{background:white;padding:20px;border-radius:13px;margin-top:20px}.pending{color:#667085;font-size:13px}@media(max-width:800px){.layout{display:block}aside{display:grid;grid-template-columns:repeat(2,1fr);border-right:0;border-bottom:1px solid #e3e7ee}.cards{grid-template-columns:repeat(2,1fr)}main{padding:16px}.top{padding:0 14px}.brand{font-size:21px}}@media(max-width:420px){.cards{grid-template-columns:1fr 1fr}.card{padding:13px}.num{font-size:20px}}</style></head><body><header class="top"><div class="brand">MeroKhata</div><div class="user"><?=htmlspecialchars($_SESSION['name']??'User')?> · <?=htmlspecialchars(ucfirst($_SESSION['role']??''))?><a href="logout.php">Logout</a></div></header><div class="layout"><aside><a class="active" href="index.php">Dashboard</a><a href="#">Products</a><a href="#">Suppliers</a><a href="#">Purchases</a><a href="#">Stock</a><a href="#">Sales / Billing</a><a href="#">Party / Customer</a><a href="#">Reports</a><a href="#">Settings</a></aside><main><h1><?=htmlspecialchars($business['business_name'])?></h1><div class="sub"><?=htmlspecialchars($business['address']?:'Business Dashboard')?><?=!empty($business['phone'])?' · '.htmlspecialchars($business['phone']):''?></div><div class="cards"><div class="card"><small>Products</small><div class="num"><?=number_format($products)?></div></div><div class="card"><small>Suppliers</small><div class="num"><?=number_format($suppliers)?></div></div><div class="card"><small>Parties</small><div class="num"><?=number_format($parties)?></div></div><div class="card"><small>Today's Sales</small><div class="num">Rs. <?=number_format($todaySales,2)?></div></div><div class="card"><small>Total Receivable</small><div class="num">Rs. <?=number_format($receivable,2)?></div></div></div><section class="welcome"><h2>Dashboard Ready</h2><p>The authenticated MeroKhata shell is ready. Each query on this dashboard is restricted to the logged-in business ID.</p><p class="pending">Products, purchases, consolidated stock, billing, party ledger and reports will be connected module-by-module before live use.</p></section></main></div></body></html>